function importForm(box){const s=snapshot.state.project;let revision=s.revision;const title=field(box,'项目标题',s.title,'text',()=>{}),script=field(box,'参考文稿（可选）',s.script,'textarea',()=>{}),u=el('div',undefined,'upload'),video=field(u,'选择本地真人视频','','file');video.accept='video/*';u.append(button('导入视频',async()=>{await save();await upload(video.files[0],'video');await drawStep();}));box.append(u);box.insertBefore(u,box.children[1]);if(s.source){const v=el('video');v.controls=true;v.src=toolMedia(s.source.file);box.append(v,el('p','已导入原视频，原文件保留。'));}const subs=field(box,'已有字幕（可选 SRT）','','file');subs.accept='.srt';box.append(button('导入已有字幕',async()=>{await save();await upload(subs.files[0],'subtitles');await drawStep();}));saveForm=async()=>{const result=await action('update',{revision,patch:{title:title.value,script:script.value}});revision=result.revision;};}
