async function talkStep(box,mode){if(step===0){const c=card(MODES[mode].steps[0]);importForm(c);box.append(c);return;}if(step===1){const c=card(MODES[mode].steps[1]);c.append(el('p','校对字幕、试听剪切和调整语速；确认方案与导出分开。'));box.append(c);await editor(c,'roughcut');c.append(button('审阅当前粗剪方案',()=>reviewEditor(c,'roughcut')));return;}if(step===2){await stylePicker(box);return;}if(step===3){const c=card(MODES[mode].steps[3]);c.append(el('p','查看包装片段，试听原声与配乐。复杂动画由 Agent 按所选风格制作。'));box.append(c);command(c,'准备包装方案','packaging');if(snapshot.state.project.workflow.packaging==='remotion-gold')command(c,'制作已选暗金模板','auto-gold');if(mode==='hybrid')hybridPanel(c);await editor(c,'packaging');c.append(button('审阅包装与配乐',()=>reviewEditor(c,'packaging')));return;}if(step===4){const c=card('成片审看与局部修改');c.append(el('p',snapshot.state.project.scenes.length?'先核对包装关键帧，再生成和审看真实成片；旧版本输出会保留。':'本次没有动画包装，合成后可直接审看真实成片；旧版本输出会保留。'));box.append(c);command(c,'合成审看片','render');refreshButton(c);await editor(c,'keyframes');if(snapshot.state.project.scenes.length)c.append(button('审阅实际关键帧',()=>reviewEditor(c,'keyframes')));c.append(button('审阅当前成片',()=>reviewEditor(c,'final','keyframes')));return;}outputs(box);}
