async function defaultsForm(box,mode){
 const d=await api('/api/defaults?mode='+mode),c=card('常用制作设置 · '+MODES[mode].name);box.append(c);
 c.append(el('p','明确保存后，新项目采用这些参数；当前和已有项目保持自己的设置。不会自动学习临时调整，也不会授权制作。'));
 function choice(label,value,options){const l=el('label',label),n=el('select');n.id='default-'+crypto.randomUUID();l.htmlFor=n.id;for(const [v,t] of options){const o=el('option',t);o.value=v;n.append(o);}n.value=value;c.append(l,n);return n;}
 const speed=choice('默认倍速',d.values.speed,[1,1.1,1.15,1.2,1.25,1.3,1.35,1.5].map(v=>[v,v+'×']));
 const language=choice('默认本地转写语言',d.values.transcribe_language,[['auto','自动识别'],['zh','中文'],['en','英语'],['ja','日语'],['ko','韩语']]);
 const style=choice('默认包装风格',d.values.packaging,Object.values(STYLES).filter(x=>MODES[mode].styles.some(k=>STYLES[k]===x)).map(x=>[x.id,x.name]));
 const subtitles=field(c,'默认把字幕烧录到画面',d.values.subtitle_burn,'checkbox');
 async function store(values){await api('/api/defaults',{mode,revision:d.revision,patch:values});await settings();message('常用设置已记住，将用于新项目；已有工程未修改。');}
 c.append(button('保存为新项目默认',()=>store({speed:Number(speed.value),transcribe_language:language.value,packaging:style.value,subtitle_burn:subtitles.checked})));
 if(current&&snapshot.entry.mode===mode)c.append(button('记住当前项目的常用参数',async()=>{await load();const s=snapshot.state.project;await store({speed:s.speed,transcribe_language:s.transcribe_language||'auto',packaging:s.workflow.packaging,subtitle_burn:s.subtitle_burn});}));
 c.append(button('恢复原始默认',()=>store({speed:1,transcribe_language:'auto',packaging:'none',subtitle_burn:true})));
}
